import Foundation

/// A comment on an Activity (ADR-034 §2): plain text, chronological, shown as "modifié" once
/// edited. Its id is generated by the app, so a send can be replayed and its realtime echo
/// recognised.
struct ActivityComment: Identifiable, Hashable, Sendable {
    let id: UUID
    var body: String
    let createdAt: Date
    /// Set on each edit.
    var updatedAt: Date?
    let author: ActivityAuthor
    /// The viewer wrote it.
    let viewerCanEdit: Bool
    /// The viewer wrote it, or wrote the Activity.
    let viewerCanDelete: Bool

    /// Body limits of the API (ADR-034 §2), after trimming.
    static let maxBodyLength = 1_000

    /// The body as the API stores it, or nil when it cannot be sent (empty or too long).
    static func sendableBody(_ text: String) -> String? {
        let body = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !body.isEmpty, body.count <= maxBodyLength else { return nil }
        return body
    }
}

/// The newest comments, oldest first, and the cursor of the older ones (nil when there are none).
struct ActivityCommentsPage: Equatable, Sendable {
    let items: [ActivityComment]
    let previousCursor: String?
}

/// Failures of the comment routes, as the presentation needs them.
enum ActivityCommentError: Error, Equatable, Sendable {
    case offline
    case unauthorized
    /// The Activity or the comment is unknown, deleted or no longer visible.
    case notFound
    /// Any other server answer, with its machine-readable code when there is one.
    case server(code: String?)
    case network
}

/// Comments port (ADR-007): `…/v1/activities/:id/comments` in Infrastructure, faked in tests.
protocol ActivityCommentRepository: Sendable {
    /// The newest page, or the one before `before`.
    func comments(activityId: ActivityID, before: String?) async throws(ActivityCommentError) -> ActivityCommentsPage
    func comment(activityId: ActivityID, id: UUID) async throws(ActivityCommentError) -> ActivityComment
    /// Replay-safe: the same id sent again answers the stored comment.
    func add(activityId: ActivityID, id: UUID, body: String) async throws(ActivityCommentError) -> ActivityComment
    func edit(activityId: ActivityID, id: UUID, body: String) async throws(ActivityCommentError) -> ActivityComment
    func delete(activityId: ActivityID, id: UUID) async throws(ActivityCommentError)
}
